/// <summary>
/// Required for METSalesPickingListGenerationTaskController\new
/// </summary>
/// <param name = "_dataContract"><c>METSalesPickingListGenerationTaskContract</c> data contract object</param>
public void process(METSalesPickingListGenerationTaskContract _dataContract)
{
    super(_dataContract);
}

/// <summary>
/// Bug 221621: CB238 - NDC / Int xDock: D365 functional warehouse processing (F/L) - Finalization error
/// Moving existing logic in method so it can be adjusted when SO extract is called from TO finalisation
/// </summary>
/// <param name = "_salesLine"><c>SalesLine</c> record</param>
/// <returns>True if the extract status is Open or ReadyForExtract; otherwise, false.</returns>
protected boolean updateSalesParmLineCondition(SalesLine _salesLine)
{
    METOrderExtractStatus orderExtractStatus = _salesLine.metSalesLine().OrderExtractStatus;
    
    return (orderExtractStatus == METOrderExtractStatus::Open 
         || orderExtractStatus == METOrderExtractStatus::ReadyForExtract);
}

/// <summary>
/// Bug 221621: CB238 - NDC / Int xDock: D365 functional warehouse processing (F/L) - Finalization error
/// Moving existing logic in method so it can be adjusted when SO extract is called from TO finalisation
/// </summary>
/// <param name = "_salesParmLine"><c>SalesParmLine</c> record</param>
/// <param name = "_salesLine"><c>SalesLine</c> record</param>
protected void setSalesParmLineFields(SalesParmLine _salesParmLine, SalesLine _salesLine)
{
    _salesParmLine.DeliverNow = _salesLine.reservedPhysicalInSalesUnit();        
}

