/// <summary>
/// Bug 221621: CB238 - NDC / Int xDock: D365 functional warehouse processing (F/L) - Finalization error
/// Moving existing logic in method so it can be adjusted when SO extract is called from TO finalisation
/// </summary>
/// <param name = "_wmsPickingRoute"><c>WMSPickingRoute</c> record</param>
protected void triggerBusinessEvent(WMSPickingRoute _wmsPickingRoute)
{
    if (BusinessEventsConfigurationReader::isBusinessEventEnabled(classStr(METPicklistExtractionBusinessEvent)))
    {
        METPicklistExtractionBusinessEvent::newFromWMSPickingRoute(_wmsPickingRoute).send();
    }
    else
    {
        error("@MET:PicklistExtractionBusinessEventNotEnabled");
    }
}
